    74→      </div>
    75→    </div>
    76→  </div>
    77→  <script>
    78→  (function() {
    79→    var bid = "{{ block.id }}";
    80→    function check() {
    81→      if (window.__zccAppEnabled) {
    82→        var inactive = document.getElementById('zcc-inactive-' + bid);
    83→        var active = document.getElementById('zcc-active-' + bid);
    84→        if (inactive) inactive.style.display = 'none';
    85→        if (active) active.style.display = 'block';
    86→      }
    87→    }
    88→    check();
    89→    setTimeout(check, 500);
    90→    setTimeout(check, 1500);
    91→    setTimeout(check, 3000);
    92→  })();
    93→  </script>
    94→{% else %}
    95→
    96→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
    97→
    98→<div
    99→  id="zcc-widget-{{ block.id }}"
   100→  data-zcc-widget="true"
   101→  data-shop="{{ shop.permanent_domain }}"
   102→  data-api="{{ app.url }}"
   103→  data-proxy="/apps/zipcheck"
   104→  data-block="{{ block.id }}"
   105→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
   106→  {{ block.shopify_attributes }}
   107→></div>
   108→
   109→<script>
   110→(function () {
   111→  // Wait for app embed to set window.__zccAppEnabled.
   112→  // App embed (target: body) may load after this section block, so we poll briefly.
   113→  var maxWait = 3000; // ms
   114→  var interval = 50;  // ms
   115→  var elapsed = 0;
   116→
   117→  function tryInit() {
   118→    if (window.__zccAppEnabled) {
   119→      init();
   120→    } else if (elapsed < maxWait) {
   121→      elapsed += interval;
   122→      setTimeout(tryInit, interval);
   123→    }
   124→    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
   125→  }
   126→
   127→  // Start checking — if already set, runs immediately
   128→  if (document.readyState === 'loading') {
   129→    document.addEventListener('DOMContentLoaded', tryInit);
   130→  } else {
   131→    tryInit();
   132→  }
   133→
   134→  function init() {
   135→  var ROOT_ID = "zcc-widget-{{ block.id }}";
   136→  var container = document.getElementById(ROOT_ID);
   137→  if (!container) return;
   138→
   139→  var SHOP = container.dataset.shop;
   140→  // app.url resolves to the App Proxy URL (e.g. https://store.myshopify.com/apps/zipcheck).
   141→  // If for any reason it is empty (e.g. dev environment or Shopify Liquid context issue),
   142→  // fall back to the relative proxy path so the request still routes correctly through
   143→  // Shopify's App Proxy rather than hitting the store's own domain as a missing route.
   144→  var _rawApi = (container.dataset.api || "").replace(/\/$/, "");
   145→  var _proxyPath = (container.dataset.proxy || "/apps/zipcheck").replace(/\/$/, "");
   146→  // Prefer app.url when it looks like a full URL; otherwise use the relative proxy path
   147→  // (which Shopify will forward to our app via the App Proxy config).
   148→  var API_BASE = (_rawApi && _rawApi.indexOf("http") === 0) ? _rawApi : _proxyPath;
   149→
   150→  // Try embedded config from metafield first (instant, no network needed)
   151→  var configStr = container.getAttribute("data-config");
   152→  if (configStr) {
   153→    try {
   154→      renderWidget(JSON.parse(configStr));
   155→      return;
   156→    } catch (e) {
   157→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
   158→    }
   159→  }
   160→
   161→  // Fallback: fetch config from API
   162→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
   163→    .then(function (r) {
   164→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
   165→      return r.json();
   166→    })
   167→    .then(function (cfg) { renderWidget(cfg); })
   168→    .catch(function (err) {
   169→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
   170→      renderWidget({});
   171→    });
   172→
   173→  function renderWidget(cfg) {
   174→    // Merge with defaults
   175→    var D = {
   176→      position: "inline",
   177→      heading: "Check Delivery Availability",
   178→      placeholder: "Enter your zip code",
   179→      buttonText: "Check",
   180→      successMessage: "Great news! We deliver to your area.",
   181→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
   182→      notFoundMessage: "We currently do not ship to this ZIP code.",
   183→      primaryColor: "#008060",
   184→      successColor: "#008060",
   185→      errorColor: "#D72C0D",
   186→      backgroundColor: "#FFFFFF",
   187→      textColor: "#202223",
   188→      borderRadius: "8",
   189→      showEta: true,
   190→      showZone: false,
   191→      showWaitlistOnFailure: false,
   192→      showCod: true,
   193→      showReturnPolicy: true,
   194→      showCutoffTime: true,
   195→      showDeliveryDays: true,
   196→      customCss: "",
   197→      blockCartOnInvalid: false,
   198→      showSocialProof: true,
   199→    };
   200→    Object.keys(D).forEach(function (k) {
   201→      if (cfg[k] === undefined || cfg[k] === null) cfg[k] = D[k];
   202→    });
   203→
   204→    var rad = cfg.borderRadius + "px";
   205→    var WID = "zcc-" + ROOT_ID;
   206→
   207→    if (cfg.position === "floating") {
   208→      renderFloating(cfg, WID, rad);
   209→    } else if (cfg.position === "popup") {
   210→      renderPopup(cfg, WID, rad);
   211→    } else {
   212→      renderInline(cfg, WID, rad);
   213→    }
   214→
   215→    // If blockCartOnInvalid is enabled, disable ATC/Buy Now buttons on page load
   216→    // until the customer validates their ZIP code
   217→    if (cfg.blockCartOnInvalid) {
   218→      blockCartButtonsInitial();
   219→    }
   220→  }
   221→
   222→  // ── Block ATC buttons on page load (before any ZIP check) ─────────────────
   223→  function blockCartButtonsInitial() {
   224→    var ATC_SELECTORS = [
   225→      'button[name="add"]',
   226→      '.product-form__submit',
   227→      '[data-product-add]',
   228→      '.btn--add-to-cart',
   229→      '.product-form button[type="submit"]',
   230→      'button.shopify-payment-button__button',
   231→      '.shopify-payment-button button',
   232→      'button.product-form__cart-submit'
   233→    ].join(',');
   234→
   235→    function doBlock() {
   236→      try {
   237→        var atcBtns = document.querySelectorAll(ATC_SELECTORS);
   238→        atcBtns.forEach(function(b) {
   239→          if (!b.closest('[data-zcc-widget]')) {
   240→            if (!b.getAttribute('data-zcc-blocked')) {
   241→              b.setAttribute('data-zcc-orig-title', b.title || '');
   242→            }
   243→            b.disabled = true;
   244→            b.style.opacity = '0.5';
   245→            b.title = 'Please check ZIP code availability first';
   246→            b.setAttribute('data-zcc-blocked', 'true');
   247→          }
   248→        });
   249→      } catch(e) {}
   250→    }
   251→
   252→    // Block immediately + delays for dynamic buttons (Shopify Buy Now renders late)
   253→    doBlock();
   254→    setTimeout(doBlock, 500);
   255→    setTimeout(doBlock, 1500);
   256→
   257→    // MutationObserver for dynamic payment buttons
   258→    if (typeof MutationObserver !== 'undefined') {
   259→      var observer = new MutationObserver(function() { doBlock(); });
   260→      var form = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]');
   261→      if (form) {
   262→        observer.observe(form, { childList: true, subtree: true });
   263→        setTimeout(function() { observer.disconnect(); }, 10000);
   264→      }
   265→    }
   266→  }
   267→
   268→  // ── Scope custom CSS: auto-prefix selectors with widget container ID ──────
   269→  function scopeCustomCss(rawCss, wid) {
   270→    if (!rawCss) return "";
   271→    // Strip </style> tags to prevent injection
   272→    var css = rawCss.replace(/<\/style>/gi, "");
   273→    var result = "";
   274→    var i = 0;
   275→    while (i < css.length) {
   276→      // Skip whitespace
   277→      while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
   278→      if (i >= css.length) break;
   279→      // Pass through @keyframes and @font-face unchanged
   280→      if (css[i] === '@') {
   281→        var atRule = "";
   282→        var j = i;
   283→        while (j < css.length && css[j] !== '{' && css[j] !== ';') { atRule += css[j]; j++; }
   284→        var atName = atRule.trim().toLowerCase();
   285→        if (atName.indexOf("@keyframes") === 0 || atName.indexOf("@font-face") === 0) {
   286→          result += atRule;
   287→          if (j < css.length && css[j] === '{') {
   288→            var depth = 1; result += css[j]; j++;
   289→            while (j < css.length && depth > 0) {
   290→              if (css[j] === '{') depth++;
   291→              if (css[j] === '}') depth--;
   292→              result += css[j]; j++;
   293→            }
   294→          }
   295→          i = j; continue;
   296→        }
   297→        // @media: scope inner rules
   298→        if (atName.indexOf("@media") === 0) {
   299→          result += atRule;
   300→          if (j < css.length && css[j] === '{') {
   301→            result += '{'; j++;
   302→            // Collect inner content
   303→            var depth = 1; var inner = "";
   304→            while (j < css.length && depth > 0) {
   305→              if (css[j] === '{') depth++;
   306→              if (css[j] === '}') depth--;
   307→              if (depth > 0) inner += css[j];
   308→              j++;
   309→            }
   310→            result += scopeCustomCss(inner, wid);
   311→            result += '}';
   312→          }
   313→          i = j; continue;
   314→        }
   315→      }
   316→      // Regular rule: grab selector, prefix with #wid
   317→      var sel = ""; var body = "";
   318→      while (i < css.length && css[i] !== '{') { sel += css[i]; i++; }
   319→      if (i < css.length) { i++; } // skip {
   320→      var depth = 1;
   321→      while (i < css.length && depth > 0) {
   322→        if (css[i] === '{') depth++;
   323→        if (css[i] === '}') depth--;
   324→        if (depth > 0) body += css[i];
   325→        i++;
   326→      }
   327→      if (sel.trim()) {
   328→        // Split multiple selectors by comma and prefix each
   329→        var selectors = sel.split(',').map(function(s) {
   330→          s = s.trim();
   331→          if (!s) return '';
   332→          return '#' + wid + ' ' + s;
   333→        }).filter(Boolean).join(', ');
   334→        result += selectors + ' {' + body + '}';
   335→      }
   336→    }
   337→    return result;
   338→  }
   339→
   340→  // ── Shared meta/waitlist CSS — injected by all three style presets ──────────
   341→  function buildSharedCss(W, cfg) {
   342→    return (
   343→      // Spin animation for loading spinner
   344→      "@keyframes zcc-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}" +
   345→      // Button icon/label structure
   346→      W + " .zcc-btn-icon{display:inline-flex !important;align-items:center !important;flex-shrink:0 !important}" +
   347→      W + " .zcc-btn-icon svg{width:15px !important;height:15px !important;display:block !important}" +
   348→      W + " .zcc-btn-label{display:inline !important}" +
   349→      // Result card layout
   350→      W + " .zcc-result-icon{flex-shrink:0 !important;width:24px !important;height:24px !important;display:flex !important;align-items:center !important;justify-content:center !important}" +
   351→      W + " .zcc-result-icon svg{width:22px !important;height:22px !important;display:block !important}" +
   352→      W + " .zcc-result-content{flex:1 !important;min-width:0 !important}" +
   353→      W + " .zcc-result-message{font-weight:600 !important;line-height:1.4 !important}" +
   354→      // Meta info rows (ETA, zone, days, cutoff)
   355→      W + " .zcc-meta{margin-top:6px !important;font-size:13px !important;display:flex !important;align-items:center !important;gap:7px !important;color:#4b5563 !important;line-height:1.4 !important}" +
   356→      W + " .zcc-meta svg{width:14px !important;height:14px !important;flex-shrink:0 !important;opacity:0.7 !important}" +
   357→      W + " .zcc-meta strong{font-weight:600 !important;color:" + cfg.textColor + " !important}" +
   358→      W + " .zcc-meta span{flex:1 !important}" +
   359→      W + " .zcc-cutoff{margin-top:5px !important;font-size:12px !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:7px !important}" +
   360→      W + " .zcc-cutoff svg{width:13px !important;height:13px !important;flex-shrink:0 !important;opacity:0.6 !important}" +
   361→      W + " .zcc-days{margin-top:5px !important;font-size:12px !important;color:#6d7175 !important;display:flex !important;align-items:center !important;gap:7px !important}" +
   362→      W + " .zcc-days svg{width:13px !important;height:13px !important;flex-shrink:0 !important;opacity:0.6 !important}" +
   363→      // COD badge
   364→      W + " .zcc-cod{margin-top:8px !important;display:inline-flex !important;align-items:center !important;gap:5px !important;border-radius:20px !important;padding:4px 10px !important;font-size:12px !important;font-weight:600 !important}" +
   365→      W + " .zcc-cod svg{width:13px !important;height:13px !important;flex-shrink:0 !important}" +
   366→      W + " .zcc-cod--available{background:" + cfg.successColor + "12 !important;border:1px solid " + cfg.successColor + "25 !important;color:" + cfg.successColor + " !important}" +
