   480→  function wireWidget(wid, cfg, API_BASE, SHOP) {
   481→    var inp = document.getElementById(wid + "-inp");
   482→    var btn = document.getElementById(wid + "-btn");
   483→    var res = document.getElementById(wid + "-res");
   484→    if (!inp || !btn || !res) return;
   485→
   486→    function normalizeZip(raw) {
   487→      var z = raw.trim().toUpperCase();
   488→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
   489→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
   490→      return z;
   491→    }
   492→
   493→    function setBtnLoading(loading) {
   494→      var iconEl = btn.querySelector('.zcc-btn-icon');
   495→      var labelEl = btn.querySelector('.zcc-btn-label');
   496→      btn.disabled = loading;
   497→      if (loading) {
   498→        if (iconEl) iconEl.innerHTML = ICONS.spinner;
   499→        if (labelEl) labelEl.textContent = '\u2026';
   500→      } else {
   501→        if (iconEl) iconEl.innerHTML = ICONS.search;
   502→        if (labelEl) labelEl.textContent = cfg.buttonText;
   503→      }
   504→    }
   505→
   506→    function checkZip() {
   507→      var zip = normalizeZip(inp.value);
   508→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
   509→      if (!zip) { inp.focus(); return; }
   510→
   511→      setBtnLoading(true);
   512→      res.innerHTML = "";
   513→
   514→      fetch(
   515→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   516→          "&zip=" + encodeURIComponent(zip)
   517→      )
   518→        .then(function (r) {
   519→          if (!r.ok) {
   520→            // Non-2xx: try to parse JSON error body, fall back to status text
   521→            return r.json().catch(function() {
   522→              return { error: 'Server error (' + r.status + ')' };
   523→            });
   524→          }
   525→          return r.json();
   526→        })
   527→        .then(function (data) {
   528→          setBtnLoading(false);
   529→
   530→          // If the API returned an error object (no allowed field), treat as a
   531→          // transient server error and show it in the result area rather than
   532→          // falling through with undefined message text.
   533→          if (data.error && data.allowed === undefined) {
   534→            console.error('[ZipCodeChecker] API returned error:', data.error, '| API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"');
   535→            res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
   536→            try {
   537→              sessionStorage.removeItem('zcc:valid');
   538→              sessionStorage.removeItem('zcc:zip');
   539→              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
   540→            } catch(e) {}
   541→            return;
   542→          }
   543→
   544→          // Store validation result for cart page
   545→          try {
   546→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
   547→            sessionStorage.setItem('zcc:zip', zip);
   548→            sessionStorage.setItem('zcc:shop', SHOP);
   549→            // Fire custom event for other scripts to listen to
   550→            window.dispatchEvent(new CustomEvent('zcc:validated', {
   551→              detail: { valid: data.allowed, zip: zip }
   552→            }));
   553→          } catch(e) { /* sessionStorage may be unavailable */ }
   554→
   555→          if (data.allowed) {
   556→            var html = '<div class="zcc-result ok">' +
   557→              '<div class="zcc-result-icon">' + ICONS.check + '</div>' +
   558→              '<div class="zcc-result-content">' +
   559→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
   560→            if (cfg.showEta && data.eta) {
   561→              html += '<div class="zcc-meta">' + ICONS.truck + '<span>Estimated delivery: <strong>' + esc(data.eta) + '</strong></span></div>';
   562→            }
   563→            if (cfg.showZone && data.zone) {
   564→              html += '<div class="zcc-meta">' + ICONS.location + '<span>Zone: <strong>' + esc(data.zone) + '</strong></span></div>';
   565→            }
   566→            if (cfg.showDeliveryDays && data.daysOfWeek) {
   567→              var days = data.daysOfWeek.split(',').map(function(d) { return d.trim(); }).join(' \u00b7 ');
   568→              html += '<div class="zcc-meta zcc-days">' + ICONS.calendar + '<span>' + esc(days) + '</span></div>';
   569→            }
   570→            if (cfg.showCutoffTime && data.cutoffTime) {
   571→              var parts = data.cutoffTime.split(':');
   572→              var hr = parseInt(parts[0], 10);
   573→              var min = parts[1] || '00';
   574→              var ampm = hr >= 12 ? 'PM' : 'AM';
   575→              var hr12 = hr % 12 || 12;
   576→              html += '<div class="zcc-meta zcc-cutoff">' + ICONS.clock + '<span>Order by <strong>' + hr12 + ':' + min + ' ' + ampm + '</strong> for same-day</span></div>';
   577→            }
   578→            if (data.codAvailable === true) {
   579→              html += '<div class="zcc-cod zcc-cod--available">' + ICONS.card + ' Cash on Delivery Available</div>';
   580→            } else if (data.codAvailable === false) {
   581→              html += '<div class="zcc-cod zcc-cod--unavailable">' + ICONS.card + ' COD Not Available</div>';
   582→            }
   583→            if (data.returnPolicy) {
   584→              html += '<div class="zcc-return-policy">' + ICONS.refresh + '<span>' + esc(data.returnPolicy) + '</span></div>';
   585→            }
   586→            html += '</div></div>';
   587→            res.innerHTML = html;
   588→          } else {
   589→            var html = '<div class="zcc-result fail">' +
   590→              '<div class="zcc-result-icon">' + ICONS.xCircle + '</div>' +
   591→              '<div class="zcc-result-content">' +
   592→              '<div class="zcc-result-message">' + esc(data.message) + '</div>';
   593→            if (cfg.showWaitlistOnFailure) {
   594→              html +=
   595→                '<div class="zcc-wl">' +
   596→                '<button class="zcc-wl-toggle" id="' + wid + '-wl-toggle" type="button">' +
   597→                ICONS.mail +
   598→                ' Request delivery to your area</button>' +
   599→                '<div id="' + wid + '-wl-form" style="display:none;margin-top:12px">' +
   600→                '<input class="zcc-wl-input" type="text" id="' + wid + '-wl-name" placeholder="Your name" />' +
   601→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Your email" />' +
   602→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button"><span class="zcc-wl-btn-icon">' + ICONS.mail + '</span><span class="zcc-wl-btn-label">Submit Request</span></button>' +
   603→                '</div>' +
   604→                '</div>';
   605→            }
   606→            html += '</div></div>';
   607→            res.innerHTML = html;
   608→
   609→            if (cfg.showWaitlistOnFailure) {
   610→              // Wire "Request ZIP Code" toggle link
