   612→              var wlForm = document.getElementById(wid + "-wl-form");
   613→              if (wlToggle && wlForm) {
   614→                wlToggle.addEventListener("click", function(e) {
   615→                  e.preventDefault();
   616→                  wlForm.style.display = wlForm.style.display === "none" ? "block" : "none";
   617→                  wlToggle.style.display = "none";
   618→                });
   619→              }
   620→
   621→              // Social proof count
   622→              if (cfg.showSocialProof && data.waitlistCount && data.waitlistCount > 0) {
   623→                var wlSection = document.getElementById(wid + "-wl-name");
   624→                if (wlSection && wlSection.parentNode) {
   625→                  var spEl = document.createElement('div');
   626→                  spEl.className = 'zcc-social-proof';
   627→                  var count = data.waitlistCount;
   628→                  var spIcon = document.createElement('span');
   629→                  spIcon.className = 'zcc-social-proof-icon';
   630→                  spIcon.innerHTML = ICONS.users;
   631→                  var spText = document.createTextNode(' Join ' + count + ' other' + (count !== 1 ? 's' : '') + ' waiting for delivery to your area');
   632→                  spEl.appendChild(spIcon);
