   941→// ── Reusable position tile selector ─────────────────────────────────────────
   942→const PositionTile = memo(function PositionTile({
   943→  value,
   944→  label,
   945→  selected,
   946→  disabled,
   947→  onSelect,
   948→  children,
   949→}: {
   950→  value: string;
   951→  label: string;
   952→  selected: boolean;
   953→  disabled: boolean;
   954→  onSelect: (v: string) => void;
   955→  children: React.ReactNode;
   956→}) {
   957→  const handleClick = useCallback(() => {
   958→    if (!disabled) onSelect(value);
   959→  }, [disabled, onSelect, value]);
   960→
   961→  return (
   962→    <button
   963→      type="button"
   964→      aria-pressed={selected}
   965→      onClick={handleClick}
   966→      disabled={disabled}
   967→      onKeyDown={(e) => {
   968→        if ((e.key === "Enter" || e.key === " ") && !disabled) {
   969→          e.preventDefault();
   970→          onSelect(value);
   971→        }
   972→      }}
   973→      style={{
   974→        flex: 1,
   975→        minWidth: 100,
   976→        appearance: "none",
   977→        WebkitAppearance: "none",
   978→        border: "none",
   979→        borderRadius: "var(--p-border-radius-200)",
   980→        padding: "var(--p-space-300)",
   981→        cursor: disabled ? "not-allowed" : "pointer",
   982→        opacity: disabled ? 0.5 : 1,
   983→        textAlign: "center",
   984→        outline: "none",
   985→        transition: "box-shadow 0.15s ease, background 0.15s ease",
   986→        background: selected
   987→          ? "var(--p-color-bg-surface-selected)"
   988→          : "var(--p-color-bg-surface)",
   989→        boxShadow: selected
   990→          ? "0 0 0 2px var(--p-color-border-emphasis)"
   991→          : "0 0 0 1px var(--p-color-border)",
   992→        fontFamily: "inherit",
   993→        color: "inherit",
   994→        fontSize: "inherit",
   995→      }}
   996→    >
   997→      <BlockStack gap="100" inlineAlign="center">
   998→        {children}
   999→        <Text as="p" variant="bodySm" fontWeight={selected ? "semibold" : "regular"}>
  1000→          {label}
  1001→        </Text>
  1002→      </BlockStack>
  1003→    </button>
  1004→  );
  1005→});
